import { useSelector as useActorSelector } from '@xstate/react';
import { useSelector } from '@xstate/store-react';
import { fbs } from 'fbtee';
import { PressableScale } from 'pressto';
import {
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from 'react-native';
import Animated, {
  ReduceMotion,
  useAnimatedStyle,
  withTiming,
} from 'react-native-reanimated';
import { SafeAreaView } from 'react-native-safe-area-context';
import assert from '@/assert';

import {
  APP_LOCALES,
  BELIEF_LIBRARY_EVENTS,
  EMOTION_LABEL_MODES,
  MOTION_DURATION,
  ONBOARDING_EVENTS,
  REMINDER_EVENTS,
  SETTINGS_EVENTS,
} from '@/constants';
import { tabScreenContentStyle } from '@/components/ui/tab-screen-layout';
import { ScreenHeading } from '@/components/ui/screen-heading';
import { PersistentScrollView } from '@/components/ui/persistent-scroll-view';
import { SettingsActionRow } from '@/components/ui/settings-action-row';
import { actionColors, palette, surfaceColors, type } from '@/theme';
import { DataSafetyControls } from '@/features/data-safety/ui/data-safety-controls';
import { FeedbackSettingsAction } from '@/features/feedback/ui/feedback-screen';
import { LegalSettingsActions } from '@/features/legal/ui/legal-settings-actions';
import { ReleaseFooter } from '@/features/updates/ui/release-footer';
import { shouldShowUpdateControls } from '@/features/updates/domain/update-controls';
import { useAppNavigationActor } from '@/navigation/app-navigation.provider';
import { appSettingsStore } from '@/app-stores';
import { guidingBeliefLibraryStatements } from '@/features/beliefs/application/guiding-belief-library';

const _selectSettings = (state: ReturnType<typeof appSettingsStore.getSnapshot>) => state.context;
const _selectGuidingBeliefCount = (
  snapshot: ReturnType<ReturnType<typeof useAppNavigationActor>['getSnapshot']>,
) => guidingBeliefLibraryStatements({
  assignments: snapshot.context.reminderAssignments,
  statements: snapshot.context.beliefStatements,
}).length;
const selectionAnimation = {
  duration: MOTION_DURATION.STATE,
  reduceMotion: ReduceMotion.System,
};

function PreferenceOption({
  disabled = false,
  label,
  onPress,
  selected,
  style,
  testID,
  textStyle,
}: {
  disabled?: boolean;
  label: string;
  onPress: () => void;
  selected: boolean;
  style: StyleProp<ViewStyle>;
  testID: string;
  textStyle: StyleProp<TextStyle>;
}) {
  assert(label.trim().length > 0, 'Preference option label must not be blank');
  assert(testID.length > 0, 'Preference option test id must not be empty');
  const selectionStyle = useAnimatedStyle(() => ({
    opacity: withTiming(selected ? 1 : 0, selectionAnimation),
    transform: [{
      scale: withTiming(selected ? 1 : 0.96, selectionAnimation),
    }],
  }), [selected]);
  const selectionTextStyle = useAnimatedStyle(() => ({
    color: withTiming(
      selected ? actionColors.primaryForeground : palette.ink,
      selectionAnimation,
    ),
  }), [selected]);

  return (
    <PressableScale
      accessibilityRole="button"
      accessibilityState={{ disabled, selected }}
      disabled={disabled}
      onPress={onPress}
      style={[style, disabled && styles.disabledPreference]}
      testID={testID}>
      <Animated.View
        pointerEvents="none"
        style={[styles.preferenceSelection, selectionStyle]}
        testID={`${testID}-selection`}
      />
      <Animated.Text style={[textStyle, selectionTextStyle]}>
        {label}
      </Animated.Text>
    </PressableScale>
  );
}

function AppReleaseInfoCard({
  appVersion,
  updateChannel,
  gitCommit,
  showTechnicalDetails,
}: {
  appVersion: string | null;
  updateChannel: string | null;
  gitCommit: string | null;
  showTechnicalDetails: boolean;
}) {
  const shortGitCommit = gitCommit?.slice(0, 7);

  return (
    <View style={styles.releaseFooter} testID="app-release-info">
      <Text style={styles.sectionHeading}><fbt desc="App release information title">App information</fbt></Text>
      <View style={styles.releaseInfo}>
        <View style={styles.releaseInfoRow}>
          <Text style={styles.releaseInfoLabel}><fbt desc="App version information label">App</fbt></Text>
          <Text selectable style={styles.releaseInfoValue}>{appVersion ?? <fbt desc="Unavailable app version value">Not available</fbt>}</Text>
        </View>
        {showTechnicalDetails ? (
          <>
            <View style={styles.releaseInfoRow}>
              <Text style={styles.releaseInfoLabel}><fbt desc="EAS Update channel information label">Channel</fbt></Text>
              <Text selectable style={styles.releaseInfoValue}>{updateChannel ?? <fbt desc="Unavailable EAS Update channel value">Not available</fbt>}</Text>
            </View>
            <View style={styles.releaseInfoRow}>
              <Text style={styles.releaseInfoLabel}><fbt desc="Git commit information label">Git</fbt></Text>
              <Text selectable style={styles.releaseInfoValue}>{shortGitCommit ?? <fbt desc="Unavailable Git commit value">Not available</fbt>}</Text>
            </View>
          </>
        ) : null}
      </View>
    </View>
  );
}

export function SettingsScreen({
  showTechnicalDetails,
}: {
  showTechnicalDetails?: boolean;
} = {}) {
  const actor = useAppNavigationActor();
  const {
    locale,
    emotionLabelMode,
    appVersion,
    updateChannel,
    gitCommit,
  } = useSelector(appSettingsStore, _selectSettings);
  const technicalDetailsVisible = showTechnicalDetails ?? shouldShowUpdateControls({
    isDevelopment: __DEV__,
    updateChannel,
  });
  const guidingBeliefCount = useActorSelector(actor, _selectGuidingBeliefCount);
  assert(locale === APP_LOCALES.ENGLISH || locale === APP_LOCALES.GERMAN, 'Settings locale must be supported');
  assert(emotionLabelMode === EMOTION_LABEL_MODES.EMOJI || emotionLabelMode === EMOTION_LABEL_MODES.TEXT || emotionLabelMode === EMOTION_LABEL_MODES.BOTH, 'Emotion label mode must be supported');
  const _setEnglish = () => actor.send({
    type: SETTINGS_EVENTS.LANGUAGE_CHANGED,
    locale: APP_LOCALES.ENGLISH,
  });
  const _setGerman = () => actor.send({
    type: SETTINGS_EVENTS.LANGUAGE_CHANGED,
    locale: APP_LOCALES.GERMAN,
  });
  const _showEmoji = () => actor.send({ type: SETTINGS_EVENTS.EMOTION_LABEL_MODE_CHANGED, mode: EMOTION_LABEL_MODES.EMOJI });
  const _showText = () => actor.send({ type: SETTINGS_EVENTS.EMOTION_LABEL_MODE_CHANGED, mode: EMOTION_LABEL_MODES.TEXT });
  const _showBoth = () => actor.send({ type: SETTINGS_EVENTS.EMOTION_LABEL_MODE_CHANGED, mode: EMOTION_LABEL_MODES.BOTH });
  const _openOnboarding = () => actor.send({ type: ONBOARDING_EVENTS.OPENED });
  const _openBeliefLibrary = () => actor.send({ type: BELIEF_LIBRARY_EVENTS.OPENED });
  const _openReminders = () => actor.send({ type: REMINDER_EVENTS.OPENED });

  return (
    <View style={styles.page} testID="settings-screen">
      <SafeAreaView edges={['top']} style={styles.safeArea}>
        <PersistentScrollView contentContainerStyle={styles.content}>
        <ScreenHeading.Root>
          <ScreenHeading.EyebrowText testID="settings-eyebrow"><fbt desc="Settings screen eyebrow heading">SETTINGS</fbt></ScreenHeading.EyebrowText>
          <ScreenHeading.TitleText style={styles.titleLayout}><fbt desc="Settings screen title">Your space.</fbt></ScreenHeading.TitleText>
        </ScreenHeading.Root>
        <Text style={styles.sectionHeading}>
          <fbt desc="Heading grouping app preferences in settings">PREFERENCES</fbt>
        </Text>
        <View style={styles.preferencesCard}>
          <View style={styles.preferenceGroup}>
          <Text style={styles.cardTitle}><fbt desc="Language setting title">Language</fbt></Text>
          <Text style={styles.cardCopy}><fbt desc="Language setting explanation">Choose the language used throughout Youmotion.</fbt></Text>
          <View style={styles.languageRow}>
            <PreferenceOption
              label={String(fbs('English', 'English language option'))}
              onPress={_setEnglish}
              selected={locale === APP_LOCALES.ENGLISH}
              style={styles.languageButton}
              testID="language-english"
              textStyle={styles.languageText}
            />
            <PreferenceOption
              label={String(fbs('German', 'German language option'))}
              onPress={_setGerman}
              selected={locale === APP_LOCALES.GERMAN}
              style={styles.languageButton}
              testID="language-german"
              textStyle={styles.languageText}
            />
          </View>
          </View>
          <View style={styles.preferenceDivider} />
          <View style={styles.preferenceGroup}>
          <Text style={styles.cardTitle}><fbt desc="Feeling pulse label display setting title">Emotion labels</fbt></Text>
          <Text style={styles.cardCopy}><fbt desc="Explanation of the feeling pulse label display setting">Choose what appears around the feeling pulse before you touch it.</fbt></Text>
          <View style={styles.labelModeRow}>
            <PreferenceOption
              label={String(fbs('Emoji', 'Emoji-only emotion label display option'))}
              onPress={_showEmoji}
              selected={emotionLabelMode === EMOTION_LABEL_MODES.EMOJI}
              style={styles.labelModeButton}
              testID="emotion-label-mode-emoji"
              textStyle={styles.labelModeText}
            />
            <PreferenceOption
              label={String(fbs('Text', 'Text-only emotion label display option'))}
              onPress={_showText}
              selected={emotionLabelMode === EMOTION_LABEL_MODES.TEXT}
              style={styles.labelModeButton}
              testID="emotion-label-mode-text"
              textStyle={styles.labelModeText}
            />
            <PreferenceOption
              label={String(fbs('Both', 'Emoji and text emotion label display option'))}
              onPress={_showBoth}
              selected={emotionLabelMode === EMOTION_LABEL_MODES.BOTH}
              style={styles.labelModeButton}
              testID="emotion-label-mode-both"
              textStyle={styles.labelModeText}
            />
          </View>
          </View>
        </View>
        <Text style={styles.sectionHeading}>
          <fbt desc="Heading grouping support links in settings">SUPPORT</fbt>
        </Text>
        <View style={styles.actionGroup}>
          <FeedbackSettingsAction />
        </View>
        <Text style={styles.sectionHeading}>
          <fbt desc="Heading for the Settings onboarding replay action">UNDERSTAND YOUMOTION</fbt>
        </Text>
        <View style={styles.actionGroup}>
          <SettingsActionRow
            description={String(fbs(
              'Replay the short guide to the Pulse, reflection, and optional beliefs.',
              'Settings explanation of the onboarding replay action',
            ))}
            onPress={_openOnboarding}
            testID="open-onboarding"
            title={String(fbs(
              'Open short guide',
              'Settings button that replays the explanation onboarding',
            ))}
          />
        </View>
        <Text style={styles.sectionHeading}>
          <fbt desc="Heading grouping personalization links in settings">PERSONALIZE</fbt>
        </Text>
        <View style={styles.actionGroup}>
          <SettingsActionRow
            description={String(fbs(
              'Choose days and times for a gentle invitation to notice how you feel.',
              'Emotion check-in reminder settings entry explanation',
            ))}
            onPress={_openReminders}
            testID="open-reminders"
            title={String(fbs(
              'Emotion check-in reminder',
              'Emotion check-in reminder settings entry title',
            ))}
          />
          <SettingsActionRow
            count={guidingBeliefCount}
            description={String(fbs(
              'Manage each guiding belief and its gentle reminder.',
              'Personal core-belief management setting explanation',
            ))}
            onPress={_openBeliefLibrary}
            testID="open-belief-library"
            title={String(fbs(
              'Manage guiding belief',
              'Button opening personal core-belief management',
            ))}
          />
        </View>
        <View testID="settings-legal-section">
          <Text style={styles.sectionHeading}>
            <fbt desc="Heading grouping legal documents in settings">LEGAL</fbt>
          </Text>
          <LegalSettingsActions locale={locale} />
        </View>
        <Text style={styles.sectionHeading}>
          <fbt desc="Heading grouping data and product information in settings">YOUR DATA</fbt>
        </Text>
        <DataSafetyControls locale={locale} />
        <View style={styles.infoGroup}>
          <View style={styles.infoRow}>
            <Text style={styles.infoTitle}><fbt desc="About the feeling pulse setting title">About the feeling pulse</fbt></Text>
            <Text style={styles.infoCopy}><fbt desc="Explanation of the feeling pulse and its purpose">The feeling pulse brings seven emotional directions together. Youmotion supports self-reflection, not diagnosis.</fbt></Text>
          </View>
        </View>
        <AppReleaseInfoCard
          appVersion={appVersion}
          gitCommit={gitCommit}
          showTechnicalDetails={technicalDetailsVisible}
          updateChannel={updateChannel}
        />
        {technicalDetailsVisible ? <ReleaseFooter testID="workspace-release" /> : null}
        </PersistentScrollView>
      </SafeAreaView>
    </View>
  );
}

