      }));
      return { context: { beliefStatements, beliefStatementsHydrated: true } };
    },
    [CHECK_IN_EVENTS.BELIEF_STATEMENTS_HYDRATION_FAILED]: {
      context: ({ event }) => ({ error: event.message, beliefStatementsHydrated: true }),
