  reset: () => void;
}
export function createInsightNotificationRuntime(): InsightNotificationRuntime {
  const coordinator = new InsightNotificationCoordinator({ store: insightNotificationStore, deps: systemInsightDependencies });
  return {
    start(binding) {
      let previous: InsightData | undefined;
      const notify = () => {
        const data = binding.data();
        if (previous?.entries === data.entries && previous.statements === data.statements
          && previous.locale === data.locale && previous.ready === data.ready) return;
        previous = data;
