import { afterEach, describe, expect, render, test, waitUntil } from 'react-native-harness';
import { Text, View } from 'react-native';
import * as Notifications from 'expo-notifications';
import { reconcileInsightBatch, cancelInsightNotifications } from '../infrastructure/insight-notification.scheduler';
import { APP_LOCALES, INSIGHT_NOTIFICATION_OWNER } from '@/constants';

afterEach(cancelInsightNotifications);
describe('native background insight delivery QA', () => {
  test('OS delivers a one-shot precomputed insight after leaving the app', async () => {
    const permission = await Notifications.requestPermissionsAsync();
    expect(permission.granted).toBe(true);
    await reconcileInsightBatch({ batch: { id: 'insight-harness-background-delivery', fireAt: new Date(Date.now() + 30000).toISOString(), candidates: [{ id: 'lastWeek:emotion:freude', timeframe: 'lastWeek', tab: 'pattern', patternId: 'emotion:freude' }] }, locale: APP_LOCALES.GERMAN });
