    await waitUntil(async () => !(await Notifications.getAllScheduledNotificationsAsync()).some((request) => request.identifier === 'insight-harness-background-delivery'), { timeout: 90000 });
    expect((await Notifications.getAllScheduledNotificationsAsync()).some((request) => request.content.data?.['owner'] === INSIGHT_NOTIFICATION_OWNER)).toBe(false);
  });
});
EOF
